import {COLORS,ATTRS,PROFILES} from './model.mjs';
export const WIDTH=1920,HEIGHT=1431;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const text=(x,y,s,size=24,fill='#e7e5dc',family='Arial',extra='')=>`<text x="${x}" y="${y}" font-size="${size}" fill="${E(fill)}" font-family="${family}" ${extra}>${E(s)}</text>`;
const ctx=document.createElement('canvas').getContext('2d');
function lines(body,width,size,family='Arial'){ctx.font=`${size}px ${family}`;let out=[];for(const para of String(body).split('\n')){let cur='';for(const word of para.split(/\s+/)){const test=(cur+' '+word).trim();if(cur&&ctx.measureText(test).width>width){out.push(cur);cur=word;}else cur=test;}out.push(cur);}return out;}
function para(body,width,height,size,color='#deddd5',align='left'){let ls=lines(body,width,size);while(ls.length*size*1.42>height&&size>12){size--;ls=lines(body,width,size);}const anchor=align==='center'?'middle':align==='right'?'end':'start';const x=align==='center'?width/2:align==='right'?width:0;return ls.map((s,i)=>text(x,(i+1)*size*1.42,s,size,color,'Arial',`text-anchor="${anchor}"`)).join('');}
function fit(s,width,size,family='Georgia'){ctx.font=`bold ${size}px ${family}`;while(ctx.measureText(s).width>width&&size>12){size--;ctx.font=`bold ${size}px ${family}`;}return size;}
function ribbon(label,width,color,size=29){const fs=fit(label,width-25,size);ctx.font=`bold ${fs}px Georgia`;const w=Math.min(width,ctx.measureText(label).width+35);return `<path d="M0 0 ${w+7} -2 ${w-3} 39 3 41Z" fill="${E(color)}"/>`+text(14,29,label,fs,'#f3f1e8','Georgia','font-weight="bold"');}
function die(cx,cy,n,size,color){let pts;const r=size/2;if(n===4)pts=[[cx,cy-r-2],[cx+r+2,cy+r],[cx-r-2,cy+r]];else if(n===6)pts=[[cx-r,cy-r],[cx+r,cy-r],[cx+r,cy+r],[cx-r,cy+r]];else if(n===8)pts=[[cx,cy-r-3],[cx+r+3,cy],[cx,cy+r+3],[cx-r-3,cy]];else {const count=n===12?5:6;pts=Array.from({length:count},(_,i)=>[cx+Math.cos(-Math.PI/2+2*Math.PI*i/count)*(r+3),cy+Math.sin(-Math.PI/2+2*Math.PI*i/count)*(r+3)]);}return `<polygon points="${pts.map(p=>p.join(',')).join(' ')}" fill="${E(color)}"/>`+text(cx,cy+size*.24,n,size*.72,'#080a0a','Arial','font-weight="bold" text-anchor="middle"');}
function resourceValue(b,d){const key=b.resource||'pv',max=Number(d[key])||0,cur=Number(d[key==='pv'?'currentPV':'currentPD'])||0;return text(0,32,cur===max?max:`${cur}/${max}`,b.font,'#f4f0e8','Georgia','font-style="italic"');}
function resourceTrack(b,d,play){const key=b.resource||'pv',max=Number(d[key])||0,cur=Number(d[key==='pv'?'currentPV':'currentPD'])||0,cols=10,rows=Math.max(1,Math.ceil(max/cols)),step=Math.min((b.w-8)/cols,b.h/rows),sz=Math.min(22,step*.78);let s='';for(let i=0;i<max;i++){const x=i%cols*step,y=Math.floor(i/cols)*step;s+=`<path ${play?`data-point="${i+1}" data-resource="${key}"`:''} d="M${x+3} ${y}h${sz}l-3 ${sz}h-${sz}Z" fill="${i<cur?'#eeeae2':'#30352e'}" ${play?'style="cursor:pointer"':''}/>`;}return s;}
function resource(b,d,a,play){return ribbon(b.resource==='pd'?'PD':'PV',90,a,b.font+8)+`<g transform="translate(107,0)">${resourceValue(b,d)}</g><g transform="translate(0,58)">${resourceTrack({...b,h:b.h-58},d,play)}</g>`;}
function counter(b,color,play){const size=Math.min(24,b.h-5),count=Math.max(1,Math.min(30,b.max||3)),prep=b.counterKind==='preparation'||String(b.title||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes('prepara');let s=b.part==='content'?'':text(0,b.h*.63,b.title.toUpperCase(),b.font,color,'Arial','font-weight="bold"');for(let i=0;i<count;i++){const x=b.w-(count-i)*(size+7),y=(b.h-size)/2,checked=i<(b.value||0);s+=`<rect x="${x}" y="${y}" width="${size}" height="${size}" rx="3" fill="${prep?'#f5f3eb':checked?E(color):'#252a23'}" stroke="${prep?'#f5f3eb':E(color)}" ${play?`data-counter="${E(b.id)}" data-point="${i+1}" style="cursor:pointer"`:''}/>`;if(prep&&checked)s+=`<path d="M${x+5} ${y+size*.5}l${size*.18} ${size*.18} ${size*.36}-${size*.38}" fill="none" stroke="#11170e" stroke-width="2.5" pointer-events="none"/>`;}return s;}
export function headingLabel(b,d){if(b.headingText!==undefined)return String(b.headingText);const source=d.blocks.find(x=>x.id===b.titleOf);if(!source)return b.title||'Título';if(source.type==='profile')return source.customTitle||PROFILES[d.profile][0];if(source.type==='ability')return d.abilities.find(a=>a.id===source.ref)?.title||b.title;return source.title||b.title;}
function frame(a){return `<g stroke="${E(a)}" stroke-width="1.5" fill="none"><path d="M82 51H1838V1380H82Z M65 67H1854V1364H65Z"/><path d="M50 91H108V35 M1812 35V91H1870 M50 1338H108V1395 M1812 1395V1338H1870"/></g><g stroke="#080a0a" stroke-width="4">${[155,325,529,706,1021,1390,1610,1702].map(x=>`<path d="M${x} 54l18-8 M${x+20} 1382l15-9"/>`).join('')}</g>`;}
export function visibleSkills(b,d,skills){const map=new Map(skills.map(row=>[row[0],row]));const ordered=[...(b.skillOrder||[]).map(k=>map.get(k)).filter(Boolean),...skills.filter(row=>!(b.skillOrder||[]).includes(row[0]))];const apt=['Artes','Atualidades','Burocracia','Exatas','Humanas','Tatica'];return ordered.filter(([key])=>{if((b.hiddenSkills||[]).includes(key))return false;if(b.onlyTrained&&(d.skills[key]||4)===4)return false;if(!b.showAllAptitudes){if(apt.includes(key)&&(d.skills[key]||4)===4)return false;if(key==='Outras'&&apt.some(k=>(d.skills[k]||4)>4))return false;}return true;});}
export function sheetSVG(d,skills,images={},options={}){
 const a=d.accent||COLORS[d.profile],bg=d.background||'#080a0a';let s=`<defs><filter id="paper"><feTurbulence baseFrequency=".63" numOctaves="3" seed="7" stitchTiles="stitch"/><feColorMatrix type="saturate" values="0"/><feComponentTransfer><feFuncA type="linear" slope=".045"/></feComponentTransfer></filter></defs><rect width="1920" height="1431" fill="${E(bg)}"/><rect width="1920" height="1431" filter="url(#paper)" opacity=".5"/>`;if(d.showFrame)s+=frame(a);
 for(const b of d.blocks){if(!b.visible)continue;const color=b.color||a;let inner='';const title=(b.title||'').toUpperCase();
  if(b.type==='name'){const fs=fit(d.name.toUpperCase(),b.w,b.font);inner=text(b.w*.5,fs,d.name.toUpperCase(),fs,color,'Georgia','font-weight="bold" text-anchor="middle"')+`<path d="M0 ${Math.min(b.h-2,fs+17)}H${b.w}" stroke="${E(color)}"/>`;}
  else if(b.type==='identity'){inner=ribbon(d.profile.toUpperCase(),b.w*.5,color,b.font)+text(b.w*.49,28,d.level?`${d.origin} • ${d.level}`:d.origin,b.font*.7,'#dddcd3','Georgia')+text(0,69,d.role,fit(d.role,b.w,17,'Arial'),'#a9aaa1','Arial');}
  else if(b.type==='portrait'||b.type==='image'){const src=b.type==='portrait'?d.portrait:b.image;if(src)inner=`<image href="${E(images[src]||src)}" width="${b.w}" height="${b.h}" preserveAspectRatio="${(b.fit||d.imageFit)==='cover'?'xMidYMid slice':'xMidYMid meet'}"/>`;else inner=options.interactive?`<rect width="${b.w}" height="${b.h}" fill="none" stroke="${E(color)}" stroke-dasharray="6 10" opacity=".35"/>`+text(b.w/2,b.h/2,'ADICIONAR RETRATO',23,color,'Arial','text-anchor="middle"'):'';}
  else if(b.type==='heading'){const label=headingLabel(b,d).toUpperCase();inner=b.headingStyle==='plain'?text(0,b.h*.63,label,b.font,color,'Arial','font-weight="bold"'):ribbon(label,b.w,color,b.font);}
  else if(b.type==='attributes'){inner=b.part==='content'?'':`<g transform="translate(0,42)">${ribbon('ATRIBUTOS',b.w*.43,color,29)}</g>`;const step=(b.h-35)/3;Object.entries(d.attrs).forEach(([k,v],i)=>{const y=31+i*step;inner+=text(b.w-94,y+13,ATTRS[k].toUpperCase(),Math.min(b.font,step*.7),'#eeeae2','Georgia','text-anchor="end" font-weight="bold"')+die(b.w-40,y,v,43,color);});}
  else if(b.type==='attributeRow'){const attr=b.attr||'Fisico';inner=text(b.w-94,44,ATTRS[attr].toUpperCase(),b.font,'#eeeae2','Georgia','text-anchor="end" font-weight="bold"')+die(b.w-40,31,d.attrs[attr],43,color);}
  else if(b.type==='skills'||b.type==='skillRow'){inner=b.type==='skillRow'||b.part==='content'?'':ribbon('PERÍCIAS',210,color,29);const rows=b.type==='skillRow'?[[b.skillKey,b.skillLabel,b.skillAttr]]:visibleSkills(b,d,skills);const step=(b.h-(b.part==='content'?11:65))/Math.max(1,rows.length);const fs=b.type==='skillRow'?b.font:Math.min(b.font,step*.77);rows.forEach(([key,label,attr],i)=>{const y=(b.type==='skillRow'||b.part==='content'?23:77)+i*step,v=d.skills[key]||4;inner+=text(b.w-169,y+7,label,fs,'#e2dfd5','Georgia','text-anchor="end"')+die(b.w-143,y,v,23,v>4?color:'#9fa9a4')+text(b.w-111,y+7,'+',22,color,'Arial','font-weight="bold"')+die(b.w-73,y,d.attrs[attr],21,color)+text(b.w-49,y+6,{'Fisico':'FÍS','Mente':'MEN','Emocao':'EMO'}[attr],12.5,color);});}
  else if(b.type==='resource')inner=resource(b,d,color,options.play);
  else if(b.type==='resourceValue')inner=resourceValue(b,d);
  else if(b.type==='resourceTrack')inner=resourceTrack(b,d,options.play);
  else if(b.type==='counter')inner=counter(b,color,options.play);
  else if(['profile','ability','text','equipment'].includes(b.type)){let label=title,body=b.body??'';if(b.type==='profile'){label=b.customTitle||PROFILES[d.profile][0].toUpperCase();body=b.body??PROFILES[d.profile][1];}if(b.type==='ability'){const ab=d.abilities.find(x=>x.id===b.ref);label=ab?.title||b.title;body=ab?.body??b.body??'';}if(b.type==='equipment')body=d.equipment;inner=b.part==='content'?para(body,b.w,b.h,b.font,b.textColor||'#deddd5',b.align):ribbon(String(label).toUpperCase(),b.w,color,b.font+4)+`<g transform="translate(5,48)">${para(body,b.w-12,b.h-53,b.font,b.textColor||'#deddd5',b.align)}</g>`;}
  else if(b.type==='rituals'){const content=b.part==='content';inner=content?'':ribbon('RITUAIS',b.w,color,b.font+6);const per=(b.h-(content?0:56))/Math.max(1,d.rituals.length);d.rituals.forEach((r,i)=>{const y=(content?1:57)+i*per;const fs=fit(r.title.toUpperCase(),b.w-10,Math.min(25,b.font+1),'Arial');inner+=text(5,y+fs,r.title.toUpperCase(),fs,color,'Arial','font-weight="bold"')+`<g transform="translate(5,${y+fs+5})">${para(r.summary||r.body,b.w-12,per-fs-10,Math.min(b.font,22))}</g>`;});}
  else if(b.type==='separator')inner=`<path d="M0 ${b.h/2}H${b.w}" stroke="${E(color)}" stroke-width="2"/>`;
  s+=`<g class="sheet-block" data-block="${E(b.id)}" transform="translate(${b.x},${b.y})" opacity="${b.opacity??1}">${options.interactive?`<rect width="${b.w}" height="${b.h}" fill="transparent"/>`:''}${inner}</g>`;
 }
 return s;
}
